    """ Return the highest nesting level for parens in this string. """
    stack = []
    max_level = -1
    level = -1

    for i, letter in enumerate(paren_string):
        if letter == "(":
            stack.append(letter)
            level += 1
            if level > max_level:
                max_level = level

        if letter == ")":
            stack.pop()
            level -= 1

    return max_level


