class Solution:

    def median_absolute_deviation(self, nums: List[float]) -> float:
        """ Find median absolute deviation for given list of input numbers
        >>> Solution().median_absolute_deviation([1.0, 2.0, 3.0, 4.0])
        1.0
        """
        assert type(nums) == list
        assert len(nums) > 0, 'Empty List'
        if len(nums) % 2 == 0:
            left_half = nums[len(nums) // 2 - 1:] + nums[:len(nums) // 2]
        else:
            left_half = nums[:(len(nums) // 2 + 1)]

        median = nums[len(nums) // 2]

        dev = []
        for num in nums:
            diff = abs(num - median)
            dev.append(diff)

        return max(mean_absolute_deviation(left_half), mean_absolute_deviation(dev))

