def parse_nested_parens_helper(string: str) -> List[List[str]]:
    """ Helper to parse_nested_parens
    """
    if not string:
        return

    stack = [(0, string)]
    res = []

    while stack:
        level, next_string = stack.pop()
        if len(next_string) == 0:
            res.append(level)
        else:
            if next_string[0] == '(':
                level_next = level + 1
                stack.append((level_next, next_string[1:]))
                stack.append((0, next_string[1:]))
            else:
                level_next = level - 1
                if level_next < 0:
                    # stack.append(level_next, next_string)  # error here: the error is stack.pop() is used before
                    return
                stack.append((level_next, next_string[1:]))

    return res

