def parse_inner_parens(paren_string: str) -> str:
    """
    Parses nested string to return a string in form '(()())' where parentheses are only allowed at deepest levels only.
    >>> parse_inner_parens('(()) ((())) (())')
    '(()())'
    """
    res = ''
    nesting_depth = 0
    for character in paren_string:
        if character == ')':
            nesting_depth -= 1
        elif character == '(':
            res += (
                (n - 1 for n in range(1, 1 + 1 * nesting_depth))
                if nesting_depth > 0 and res != ''
                else ()
            ) + '('
            nesting_depth += 1
        else:
            res += character
    return res


